            return .zeroAddress(ZeroAddressError())
        }
        if selector == Data([0x1f, 0x2a, 0x20, 0x05]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "ZeroAmount()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("ZeroAmount()") }
            return .zeroAmount(ZeroAmountError())
        }
        return nil
    }
}
